// Knowledge base types for "The Missing Label".
// One record per drug or drug class. The clinician Drug Card, patient messages and
// labels all read from this, so they always agree (spec §3.1).
//
// Generated by scripts/build_knowledge_base.py -> data/kb/knowledge_base.json
// Mock for UI work: data/kb/mock_knowledge_base.json (same shape, 3 drugs).
// JSON Schema: schemas/knowledge_base.schema.json (keep the two in sync).
//
// Hard rules encoded here:
// - No dose numbers anywhere. The Heat Dose Compass is an arrow, never a number.
// - Claims with badge "?" (unverified) have public=false. UI must not show them on
//   labels or in patient messages (filter with isPublicClaim()).
// - Graph pathways (layer "graph") and FDA reports (layer "fda_reports") are shown
//   separately and never blended into the literature evidence score.

export type DrugId = string; // e.g. "lithium", "loop_diuretics", "anticholinergics_oxybutynin"

/** The four action buckets (spec §3.3). One colour each, used everywhere. */
export type Bucket = "adjust_dose" | "hold_or_substitute" | "monitor" | "storage";

/** Plain 3-step meter shown on main screens (spec C8). */
export type Meter = "strong" | "some" | "early_signs";

/** 8-step evidence tier (spec §9), shown in nerd stats. 1 = strongest. */
export type TierCode = 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
export interface Tier {
  code: TierCode;
  label: string; // "RCT / meta-analysis" ... "Mechanism only"
}

export type Direction =
  | "supports_harm"
  | "null"
  | "conflicting"
  | "protective"
  | "plausible_untested"
  | "evidence_gap";

/** Verification badges (spec §8.2a). "?" is never public. */
export type Badge = "✓✓" | "✓" | "↗" | "⚠" | "?";
export type BadgeCode = "double_verified" | "verified" | "corroborated" | "conflict" | "unverified";

/** Evidence layers (spec C9): ① System graph, ② literature, ③ FDA adverse-event reports. */
export type Layer = "graph" | "literature" | "fda_reports" | "label" | "guidance";

export type Level = "high" | "moderate" | "low";

export interface Ingredient {
  name: string; // generic ingredient, lowercase
  rxcui: string | null; // RxNorm ingredient RxCUI (null if lookup failed)
  rxnorm_name: string | null;
  tty: string | null; // IN / PIN / MIN
  acb_score: number | null; // Anticholinergic Cognitive Burden 2012 (null = not listed on the scale)
}

export interface Names {
  display: string; // "Lithium"
  plain: string; // patient-facing name, e.g. "Water pills (loop diuretics)"
  class_label: string; // "Mood stabilizer"
  examples: string[]; // generic examples, no brand names
  ingredients: Ingredient[];
  master_list_rows: string[]; // R-ids in data/Drug heat risk master list.csv
}

export interface BucketAssignment {
  bucket: Bucket;
  primary: boolean;
  rationale: string;
}

export interface ScoreComponents {
  design_weight: number; // from best tier among public literature claims
  independent_studies: number; // count of distinct literature sources (public claims)
  study_factor: number; // min(1, log2(1+n)/log2(1+5))
  consistency: number; // share of literature claims in the majority direction
  population_match: number; // 1 real patients in heat ... 0.3 mechanism only
}

export interface EvidenceSummary {
  meter: Meter;
  meter_label: "Strong" | "Some" | "Early signs";
  tier: Tier; // best tier among public literature claims (or curated floor)
  literature_score: number; // 0..1 = product of components; literature only
  components: ScoreComponents;
  direction: Direction;
  null_or_conflicting: string[]; // claim ids that are null/conflicting: shown, not hidden
  plain_summary: string;
}

export interface MeterWithRationale {
  level: Level;
  plain_label: string; // FLAG: "Check on this person"; CHANGE: "Rethink the medicine"
  score?: number; // formula in evidence_model.flag_change_rules
  rationale: string;
  drivers: string[]; // short machine-readable reasons
}

export type CompassArrow = "up" | "down" | "depends";
export interface HeatDoseCompass {
  arrow: CompassArrow;
  symbol: "↑" | "↓" | "↕";
  meaning: string; // "Drug acts stronger in heat" etc. NEVER a dose number.
  mechanism: string;
  triggers: string[]; // "forecast heat", "fever", "exertion", "heat on a patch"
  monitor: string[];
  evidence_meter: Meter;
  source_claim_ids: string[];
  note: string; // "Direction only, not doses..."
}

export type HeatDefense = "sweating" | "water_salt" | "kidney_clearance" | "blood_pressure";
export interface HeatStackEntry {
  affected: "yes" | "possible" | "no";
  how: string;
}
export type HeatStack = Record<HeatDefense, HeatStackEntry> & {
  other: { defense: string; how: string }[]; // thermostat, awareness, absorption, drug integrity
};

/** §6.1 mechanism groups used for stacking / combination rules. */
export type MechanismGroup =
  | "sweat_blocked"
  | "thermostat"
  | "fluid_salt_loss"
  | "low_sodium"
  | "kidney_cleared_buildup"
  | "kidney_stress"
  | "faster_absorption"
  | "sedation_awareness"
  | "bp_drop"
  | "heat_production"
  | "blood_sugar"
  | "storage_sensitive";

export interface GuidanceSourceEntry {
  source_id: string; // CDC, NYC, UKHSA, HC, ANSM, WHO_EUR, VIC, GER_BMG, GER_HEID
  jurisdiction: string;
  mention_level: "specific" | "umbrella" | "none";
  action_type: string; // hold_or_substitute | adjust_dose | monitor | storage | general_caution | none
  specific_action: boolean;
  evidence_cited: boolean;
  quote: string; // verbatim from the source (may be non-English)
  location: string;
}
export interface GuidanceCoverage {
  n_jurisdictions: number; // 8 (Germany = BMG + Heidelberg)
  jurisdictions_mentioning: number;
  jurisdictions_specific_action: number;
  gap: boolean; // ring / "!" badge: no jurisdiction gives a drug-specific action
  gap_reason: string;
  by_source: GuidanceSourceEntry[];
  input_file: string;
}

export interface FdaLabelIngredient {
  ingredient: string;
  best_tier: string; // "heat warning" | "sweating/dehydration only (indirect)" | "storage temperature only" | ...
  three_way: string;
  n_labels_audited: number;
  n_heat_warning: number;
  pct_heat_warning?: number | null; // v2 label audit: share of audited labels with a heat warning
  example_set_id: string;
  example_section: string;
  example_snippet: string;
}
export interface FdaLabelStatus {
  class_status: "heat warning" | "indirect only" | "incidental or storage only" | "not audited";
  plain: string;
  ingredients: FdaLabelIngredient[];
  input_file: string;
}

export interface FaersRow {
  ingredient: string; // or "ALL: a+b+c" for pooled class
  level: "ingredient" | "class";
  n_cases: number;
  ror: number | null;
  ror_ci_low: number | null;
  ror_ci_high: number | null;
  signal: boolean;
  above_neg_control_band: boolean;
}
export interface FaersSignal {
  composite: string; // "HEAT COMPOSITE SPECIFIC ..."
  headline: FaersRow | null; // pooled class row if present, else the single ingredient
  rows: FaersRow[];
  neg_control_cutoff: number; // 1.734 for the specific composite
  verdict: "above negative-control band" | "signal (within noise band)" | "no signal";
  plain: string;
  caveat: "warning signal, not proof";
  input_file: string;
}

export interface GraphPathway {
  mediator: string;
  mediator_label: string;
  drug_leg_studies: number;
  heat_leg_studies: number;
  direct_drug_heat_studies: number;
  pathway_score_sqrt_studies: number;
  pathway_present: boolean;
}
export interface GraphLayer {
  source: string; // "System Public Graph, Dataverse v2.1 (+ API when present)"
  pathways: GraphPathway[];
  direct_findings: {
    pmid: string;
    drug_variable: string;
    heat_variable: string;
    statistic_type: string;
    statistic_value: number | null;
    title: string;
    flagged: boolean;
  }[];
  untested_links: string[]; // mediators where both legs exist but no direct drug x heat finding
  validation_rank_nonbp: number | null;
  api: Record<string, unknown> | null; // filled from system_api_*.csv when present
  input_files: string[];
}

export interface ClaimNumber {
  value: number;
  type: string; // OR, RR, ROR, ratio, beta, degC, n
  ci_low?: number | null;
  ci_high?: number | null;
  display: string; // "OR 2.43"
  plain: string; // "About 2½ times the odds"
}

export interface SourceRef {
  id: string; // "PMID:41044101" | "DOI:10..." | "FAERS" | "GUIDANCE:HC" | "LABEL:<set_id>"
  label: string; // "Chen et al., Sci Rep 2025"
  url: string | null;
}

export interface Claim {
  id: string; // stable, e.g. "lithium.c1"
  text: string; // clinician wording
  plain: string; // plain-language wording
  number: ClaimNumber | null;
  source: SourceRef;
  paper_key?: string; // canonical paper id (pmid:/doi:) used to count independent studies
  layer: Layer;
  tier: Tier | null; // design tier for literature claims
  population_match?: string; // key into evidence_model.population_match
  direction: Direction;
  population: string;
  badge: Badge;
  badge_code: BadgeCode;
  verification: string; // how the badge was earned (machine checks)
  citation_status: string; // from citation_verification.csv / master list
  public: boolean; // false when badge is "?"
  input_file: string; // the repo file this traces to
}

export interface Alternative {
  name: string;
  why: string;
  what_is_lost: string;
  heat_studied: boolean;
  heat_evidence_label: string; // "not studied in heat" when heat_studied=false
  source: SourceRef | null; // cited prescribing source supporting the heat-relevant difference
  caution: string; // always includes "never stop abruptly" / spring review, not automatic switch
}

export interface Combination {
  id: string;
  partners: DrugId[]; // other KB ids (may include non-KB ids like "nsaids")
  label: string;
  rule: "same_mechanism_stack" | "cross_mechanism" | "direct_evidence";
  mechanism_groups: MechanismGroup[];
  finding: string;
  direction: Direction;
  claim_ids: string[];
  plain: string;
}

export type TimelinePhase = "before_summer" | "72h_before" | "during" | "after";
export type Actor =
  | "prescriber"
  | "pharmacist"
  | "care_coordinator"
  | "patient"
  | "caregiver"
  | "health_system";
export interface TimelineAction {
  phase: TimelinePhase;
  action: string;
  who: Actor[];
  evidence_meter: Meter;
  basis: string; // claim ids, guidance source ids, or "expert consensus / guidance only"
}

export type MessageSituation = "heat_forecast" | "heat_day" | "after_heat" | "storage" | "combined";
export interface PatientMessage {
  situation: MessageSituation;
  en: string;
  es: string;
  es_status: "machine-translated, needs review";
  reading_level_note: string;
  uses_claim_ids: string[]; // all must be public
}

export interface StorageInfo {
  profile_id: string | null; // id in data/processed/drug_storage_profiles.json
  summary: string;
  input_file: string | null;
}

export interface DrugRecord {
  id: DrugId;
  scope: "core15" | "extra";
  names: Names;
  buckets: BucketAssignment[];
  mechanism_groups: MechanismGroup[];
  label_line: string; // Missing Label plain line (public claims only)
  evidence: EvidenceSummary;
  flag: MeterWithRationale;
  change: MeterWithRationale;
  compass: HeatDoseCompass;
  heat_stack: HeatStack;
  prescribers: string[];
  higher_risk_groups: string[];
  pediatric_note: string | null;
  guidance: GuidanceCoverage;
  fda_label: FdaLabelStatus;
  faers: FaersSignal | null;
  graph: GraphLayer;
  claims: Claim[];
  alternatives: Alternative[];
  combinations: Combination[];
  timeline: TimelineAction[];
  patient_messages: PatientMessage[];
  storage: StorageInfo | null;
  gaps: string[]; // what is not known; shown as gaps
  disclaimer: string;
}

export interface CombinationRule {
  id: string;
  label: string;
  rule: Combination["rule"];
  members: DrugId[];
  description: string;
  evidence: string;
  claim_ids: string[];
}

export interface KnowledgeBase {
  schema_version: string;
  build_id: string; // sha1 of inputs present (deterministic)
  disclaimer: string;
  inputs: { path: string; present: boolean; rows: number | null; sha1: string | null }[];
  evidence_model: {
    formula: string;
    design_weights: Record<string, number>;
    population_match: Record<string, number>;
    meter_thresholds: { strong: number; some: number };
    flag_change_rules: string;
  };
  anticholinergic_scale: { name: string; source: string; url: string; input_file: string };
  combination_rules: CombinationRule[];
  drugs: DrugRecord[];
}

export const isPublicClaim = (c: Claim): boolean => c.public && c.badge !== "?";

export const BUCKET_LABEL: Record<Bucket, string> = {
  adjust_dose: "Adjust dose",
  hold_or_substitute: "Hold / substitute",
  monitor: "Monitor",
  storage: "Store cool",
};

export const METER_LABEL: Record<Meter, string> = {
  strong: "Strong",
  some: "Some",
  early_signs: "Early signs",
};
